begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at)
select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'task005-'||n||'@unc.edu',now() from generate_series(1,8) n;
insert into storage.objects(bucket_id,name,owner_id)
select 'profile-photos',id::text||'/primary.png',id::text from public.accounts where id::text like '50000000-%';
update public.profiles set real_name='Fixture',major='Science',graduation_year=2028,bio='Local test',primary_photo_path=user_id::text||'/primary.png' where user_id::text like '50000000-%';
insert into public.universities(id,slug,name,active,allowed_email_domains) values('50000000-0000-4000-8000-000000000099','task005-campus','Other campus',true,array['unc.edu']);
update public.university_memberships set university_id='50000000-0000-4000-8000-000000000099' where user_id='50000000-0000-4000-8000-000000000006';
insert into public.platform_roles(user_id,role) values('50000000-0000-4000-8000-000000000003','admin'),('50000000-0000-4000-8000-000000000004','moderator');
create function pg_temp.hid() returns uuid language sql as $$select current_setting('test.hangout')::uuid$$;
create function pg_temp.st() returns timestamptz language sql as $$select current_setting('test.start')::timestamptz$$;
create function pg_temp.req() returns uuid language sql as $$select '50000000-0000-4000-8000-000000000070'::uuid$$;
create function pg_temp.fail_private_write() returns trigger language plpgsql as $$
begin
 if new.instructions='FORCE_ROLLBACK' then raise exception 'test private write failure'; end if;
 return new;
end;
$$;
create trigger test_private_atomicity before insert or update on public.hangout_private_locations
for each row execute function pg_temp.fail_private_write();
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'gate off hides public hangouts');
select is((select count(account_id) from public.hangout_participants),0::bigint,'gate off hides roster');
select is((select count(*) from public.hangout_private_locations),0::bigint,'gate off hides private details');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000070','T',now()+interval '1 hour','Area',35,-79)$$,'42501',null,'gate off denies create');
select throws_ok($$update private.hangout_feature_gate set enabled=true$$,'42501',null,'client cannot enable gate');
reset role;
update private.hangout_feature_gate set enabled=true;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.start',(now()+interval '1 hour')::text,true);
select set_config('test.hangout',public.create_hangout(pg_temp.req(),'  Tacos  ',pg_temp.st(),'  Public area  ',35,-79,E' \t ',null,'  Zone  ','  SECRET ROOM  ')::text,true);
select is((select title from public.hangouts),'Tacos','required text normalized');
select is((select description from public.hangouts),null,'optional blank normalized');
select is((select location_precision from public.hangouts),'approximate_area','approximate precision stored');
select is((select host_id from public.hangouts),auth.uid(),'host derived from caller');
select is((select revision from public.hangouts),1::bigint,'initial server revision');
select is((select count(account_id) from public.hangout_participants),1::bigint,'host atomically joined');
select is((select instructions from public.hangout_private_locations),'SECRET ROOM','host private details');
select is(public.create_hangout(pg_temp.req(),'Tacos',pg_temp.st(),'Public area',35,-79,'',null,'Zone','SECRET ROOM'),pg_temp.hid(),'normalized retry returns same ID');
select is((select count(*) from public.hangouts),1::bigint,'retry creates no duplicate');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000073','Partial',now()+interval '1 hour','Area',35,-79,p_private_instructions=>'FORCE_ROLLBACK')$$,'P0001',null,'private failure aborts create transaction');
select is((select count(*) from public.hangouts),1::bigint,'failed create leaves no public row');
select is((select count(*) from public.hangout_participants),1::bigint,'failed create leaves no host row');
reset role;
select is((select count(*) from private.hangout_create_requests),1::bigint,'failed create leaves no request ledger row');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.create_hangout(pg_temp.req(),'Conflict',pg_temp.st(),'Public area',35,-79)$$,'23505',null,'request UUID conflicting reuse denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()-interval '1 minute','Area',35,-79)$$,'22023',null,'past creation denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '367 days','Area',35,-79)$$,'22023',null,'far creation denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_ends_at=>now()+interval '8 days')$$,'22023',null,'long end denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071',repeat('t',121),now()+interval '1 hour','Area',35,-79)$$,'22023',null,'title bound');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour',repeat('p',121),35,-79)$$,'22023',null,'place bound');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_description=>repeat('d',2001))$$,'22023',null,'description bound');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_campus_zone=>repeat('z',81))$$,'22023',null,'zone bound');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_private_instructions=>repeat('s',2001))$$,'22023',null,'private bound');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_visibility=>'friends')$$,'22023',null,'friends denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_eligibility=>'{}')$$,'22023',null,'eligibility denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-79,p_location_precision=>'exact')$$,'22023',null,'exact precision denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area','NaN',-79)$$,'22023',null,'NaN denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',91,-79)$$,'22023',null,'bad latitude denied');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000071','T',now()+interval '1 hour','Area',35,-181)$$,'22023',null,'bad longitude denied');
select throws_ok($$insert into public.hangouts(title) values('Forged')$$,'42501',null,'direct insert denied');
select throws_ok($$update public.hangouts set host_id='50000000-0000-4000-8000-000000000002'$$,'42501',null,'direct update denied');
select throws_ok($$delete from public.hangouts$$,'42501',null,'direct deletion denied');
select throws_ok($$select state from public.hangout_participants$$,'42501',null,'history column denied');
select throws_ok($$select joined_at from public.hangout_participants$$,'42501',null,'timestamp column denied');
select throws_ok($$select * from private.hangout_create_requests$$,'42501',null,'request payload inaccessible');
select throws_ok($$select public.leave_hangout(pg_temp.hid())$$,'42501',null,'host cannot leave');
select is(public.get_hangout_participant_state(pg_temp.hid(),auth.uid()),'joined','host sees own state');
set local role anon;
select throws_ok($$select id from public.hangouts$$,'42501',null,'anonymous public rows denied');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'anonymous mutation denied');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'missing subject sees no public rows');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'missing subject cannot join');
reset role;
update auth.users set email_confirmed_at=null where id='50000000-0000-4000-8000-000000000007';
update public.profiles set primary_photo_path=null where user_id='50000000-0000-4000-8000-000000000008';
update public.accounts set status='banned' where id='50000000-0000-4000-8000-000000000004';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000007","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'unconfirmed reader denied');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'unconfirmed join denied');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000008","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'missing photo reader denied');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'missing photo join denied');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000004","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'banned moderator reader denied');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'banned moderator join denied');
reset role;
update public.universities set active=false where slug='unc-chapel-hill';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'inactive campus hides rows from host');
select is((select count(*) from public.hangout_private_locations),0::bigint,'inactive campus revokes host private');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'inactive campus denies mutations');
reset role;
update public.universities set active=true where slug='unc-chapel-hill';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.edit_hangout(pg_temp.hid(),1,'Edited',pg_temp.st(),'Area',35,-79,p_private_instructions=>'New secret'),2::bigint,'atomic details edit increments revision');
select is((select instructions from public.hangout_private_locations),'New secret','private edit committed');
select throws_ok($$select public.edit_hangout(pg_temp.hid(),2,'Partial edit',pg_temp.st(),'Area',35,-79,p_private_instructions=>'FORCE_ROLLBACK')$$,'P0001',null,'private failure aborts edit transaction');
select is((select title from public.hangouts),'Edited','failed private edit rolls back public title');
select is((select revision from public.hangouts),2::bigint,'failed private edit rolls back revision');
select throws_ok($$select public.edit_hangout(pg_temp.hid(),1,'Stale',pg_temp.st(),'Area',35,-79,p_private_instructions=>'Stale secret')$$,'40001',null,'stale edit rejected');
select is((select instructions from public.hangout_private_locations),'New secret','stale edit leaves private unchanged');
select throws_ok($$select public.edit_hangout(pg_temp.hid(),2,'Invalid',pg_temp.st(),'Area',35,-79,p_private_instructions=>repeat('s',2001))$$,'22023',null,'invalid private edit rejected');
select is((select title from public.hangouts),'Edited','failed edit leaves public unchanged');
select is(public.set_hangout_joining(pg_temp.hid(),2,'closed'),3::bigint,'host closes joining with CAS');
select throws_ok($$select public.set_hangout_joining(pg_temp.hid(),2,'open')$$,'40001',null,'stale lifecycle write denied');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),1::bigint,'ready campus sees public hangout');
select is((select count(*) from public.hangout_private_locations),0::bigint,'nonmember private denied');
select is((select count(account_id) from public.hangout_participants),1::bigint,'public sees current ready host ID');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'closed joining denied');
select throws_ok($$select public.edit_hangout(pg_temp.hid(),3,'Forged',pg_temp.st(),'Area',35,-79)$$,'42501',null,'nonhost edit denied');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.set_hangout_joining(pg_temp.hid(),3,'open'),4::bigint,'host reopens published joining');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.join_hangout(pg_temp.hid())$$,'ready peer joins');
select is((select instructions from public.hangout_private_locations),'New secret','joined peer reads private');
reset role;
update public.accounts set status='suspended' where id='50000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(account_id) from public.hangout_participants),1::bigint,'public roster hides no-longer-ready host');
reset role;
update public.accounts set status='active' where id='50000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(account_id) from public.hangout_participants),2::bigint,'ready host reappears in public roster');
select lives_ok($$select public.leave_hangout(pg_temp.hid())$$,'peer leaves');
select is((select count(*) from public.hangout_private_locations),0::bigint,'left peer loses private');
select is(public.get_hangout_participant_state(pg_temp.hid(),auth.uid()),'left','member sees own left state');
select lives_ok($$select public.join_hangout(pg_temp.hid())$$,'left peer rejoins');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.remove_hangout_participant(pg_temp.hid(),'50000000-0000-4000-8000-000000000002')$$,'host removes peer');
select is(public.get_hangout_participant_state(pg_temp.hid(),'50000000-0000-4000-8000-000000000002'),'removed','host sees nonpublic removal');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(public.get_hangout_participant_state(pg_temp.hid(),auth.uid()),'removed','removed member sees own state');
select is((select count(*) from public.hangout_private_locations),0::bigint,'removed peer loses private');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'removed peer cannot rejoin');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000006","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'other campus cannot read');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'other campus cannot join');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from public.hangout_private_locations),0::bigint,'admin no private bypass');
select throws_ok($$select public.cancel_hangout(pg_temp.hid(),4)$$,'42501',null,'admin cannot cancel');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.cancel_hangout(pg_temp.hid(),4),5::bigint,'host cancels with CAS');
select is((select joining_state from public.hangouts),'closed','cancel closes joining');
select is((select count(*) from public.hangout_private_locations),0::bigint,'cancel revokes host private access');
select throws_ok($$select public.edit_hangout(pg_temp.hid(),5,'Bad',pg_temp.st(),'Area',35,-79)$$,'42501',null,'cancelled edit denied');
select throws_ok($$select public.set_hangout_joining(pg_temp.hid(),5,'open')$$,'42501',null,'cancelled reopening denied');
select throws_ok($$select public.cancel_hangout(pg_temp.hid(),5)$$,'42501',null,'cancel is terminal');
select is(public.create_hangout(pg_temp.req(),'Tacos',pg_temp.st(),'Public area',35,-79,'',null,'Zone','SECRET ROOM'),pg_temp.hid(),'authorized retry after cancellation returns original ID');
select is((select count(*) from public.hangout_private_locations),0::bigint,'replay never returns cancelled private detail');
reset role;
update public.accounts set status='suspended' where id='50000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.create_hangout(pg_temp.req(),'Tacos',pg_temp.st(),'Public area',35,-79,'',null,'Zone','SECRET ROOM')$$,'42501',null,'readiness loss denies retry');
reset role;
update public.accounts set status='active' where id='50000000-0000-4000-8000-000000000001';
update public.university_memberships set university_id='50000000-0000-4000-8000-000000000099' where user_id='50000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.create_hangout(pg_temp.req(),'Tacos',pg_temp.st(),'Public area',35,-79,'',null,'Zone','SECRET ROOM')$$,'42501',null,'campus transfer denies matching replay');
select throws_ok($$select public.create_hangout(pg_temp.req(),'Different',pg_temp.st(),'Public area',35,-79,'',null,'Zone','SECRET ROOM')$$,'42501',null,'campus transfer denies conflicting replay before payload comparison');
reset role;
update public.university_memberships set university_id='00000000-0000-4000-8000-000000000001' where user_id='50000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'cancelled public hidden from nonmember');
select throws_ok($$select public.get_hangout_participant_state(pg_temp.hid(),auth.uid())$$,'42501',null,'stranger cannot probe cancelled state');
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.replay_start',(clock_timestamp()+interval '1 second')::text,true);
select set_config('test.replay_hangout',public.create_hangout('50000000-0000-4000-8000-000000000074','Near start',current_setting('test.replay_start')::timestamptz,'Area',35,-79)::text,true);
select lives_ok('select pg_sleep(1.2)','wait until original start passes');
select is(public.create_hangout('50000000-0000-4000-8000-000000000074','Near start',current_setting('test.replay_start')::timestamptz,'Area',35,-79),current_setting('test.replay_hangout')::uuid,'lost-response retry works after start passes');
reset role;
update private.hangout_feature_gate set enabled=false;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"50000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is((select count(*) from public.hangouts),0::bigint,'gate off revokes existing public read');
select is((select count(*) from public.hangout_private_locations),0::bigint,'gate off revokes private');
select is((select count(account_id) from public.hangout_participants),0::bigint,'gate off revokes roster');
select throws_ok($$select public.create_hangout('50000000-0000-4000-8000-000000000072','T',now()+interval '1 hour','Area',35,-79)$$,'42501',null,'gate off denies create after prior use');
select throws_ok($$select public.edit_hangout(pg_temp.hid(),5,'T',pg_temp.st(),'Area',35,-79)$$,'42501',null,'gate off denies edit');
select throws_ok($$select public.set_hangout_joining(pg_temp.hid(),5,'closed')$$,'42501',null,'gate off denies joining control');
select throws_ok($$select public.cancel_hangout(pg_temp.hid(),5)$$,'42501',null,'gate off denies lifecycle');
select throws_ok($$select public.join_hangout(pg_temp.hid())$$,'42501',null,'gate off denies join');
select throws_ok($$select public.leave_hangout(pg_temp.hid())$$,'42501',null,'gate off denies leave');
select throws_ok($$select public.remove_hangout_participant(pg_temp.hid(),'50000000-0000-4000-8000-000000000002')$$,'42501',null,'gate off denies removal');
select throws_ok($$select public.get_hangout_participant_state(pg_temp.hid(),'50000000-0000-4000-8000-000000000002')$$,'42501',null,'gate off denies state inspection');
select * from finish();
rollback;
